using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
public static class PortCombatAudit {
 [Serializable] class Report{public string phase,saveName,scope="Independent combat world; power plants, ammunition and turrets are fixtures. Target selection, firing, damage and kills use unchanged original game code. Does not cover player weapons, space combat, all enemy tiers or base eradication.";public int target,enemyCount,kills,initialAmmo,remainingAmmo,destroyedTurrets;public long damage,tick;public bool reloaded;public List<string> errors=new List<string>();}
 static Report r;static int[] turrets;static PlanetFactory F=>GameMain.localPlanet.factory;static string Folder=>Application.persistentDataPath;public static bool Passed{get;private set;}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Write(string phase){r.phase=phase;r.tick=GameMain.gameTick;if(turrets!=null){r.damage=0;r.kills=0;r.remainingAmmo=0;r.destroyedTurrets=0;foreach(int e in turrets){if(e<=0||F.entityPool[e].id!=e||F.entityPool[e].turretId<=0){r.destroyedTurrets++;continue;}var t=F.defenseSystem.turrets.buffer[F.entityPool[e].turretId];r.damage+=t.totalDamage;r.kills+=t.totalKillCount;r.remainingAmmo+=t.itemCount;}}File.WriteAllText(Path.Combine(Folder,"combat-audit.json"),JsonUtility.ToJson(r,true));File.AppendAllText(Path.Combine(Folder,"combat-audit.txt"),JsonUtility.ToJson(r)+"\n");}
 static int Build(int proto,Vector3 pos){var item=LDB.items.Select(proto);var n=pos.normalized;var p=n*(F.planet.data.QueryHeight(n)+.2f);var pre=new PrebuildData{protoId=(short)proto,modelIndex=(short)item.ModelIndex,pos=p,rot=Quaternion.FromToRotation(Vector3.up,n),itemRequired=0};int id=F.AddPrebuildDataWithComponents(pre);F.BuildFinally(GameMain.mainPlayer,id);for(int i=1;i<F.entityCursor;i++)if(F.entityPool[i].id==i&&F.entityPool[i].protoId==proto&&(F.entityPool[i].pos-p).sqrMagnitude<.01f)return i;throw new Exception("Combat build failed "+proto);}
 static IEnumerator Capture(string tag){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(Folder,"combat-"+tag+".png"),t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}yield return null;}
 static IEnumerator Run(){Passed=false;r=new Report();turrets=null;File.WriteAllText(Path.Combine(Folder,"combat-audit.txt"),r.scope+"\n");Write("new_combat_world");var desc=new GameDesc();desc.SetForNewGame(UniverseGen.algoVersion,20261011,64,1,1);desc.isPeaceMode=false;DSPGame.StartGameSkipPrologue(desc);yield return null;float deadline=Time.realtimeSinceStartup+240;while((!GameMain.isRunning||DSPGame.IsMenuDemo||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded||GameMain.gameTick<120)&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(1);Check(GameMain.isRunning&&!DSPGame.IsMenuDemo&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded,"Combat world timeout");Check(GameMain.data.gameDesc.isCombatMode,"Combat mode absent");
  int target=0;for(int i=1;i<F.enemyCursor;i++)if(F.enemyPool[i].id==i&&!F.enemyPool[i].isInvincible){r.enemyCount++;if(target==0||F.enemyPool[i].dfGConnectorId>0)target=i;}Check(target>0,"No natural ground enemies");r.target=target;Vector3 centre=(Vector3)F.enemyPool[target].pos;var up=centre.normalized;var right=Vector3.Cross(up,Vector3.forward).normalized;var forward=Vector3.Cross(right,up).normalized;
  ItemProto gen=null,pole=null,gauss=null,laser=null,ammo=null;foreach(var it in LDB.items.dataArray){var d=it.prefabDesc;if(d!=null){if(d.isPowerGen&&d.fuelMask>0&&!d.gammaRayReceiver&&(gen==null||d.genEnergyPerTick>gen.prefabDesc.genEnergyPerTick))gen=it;if(d.isPowerNode&&!d.isPowerGen&&!d.isAccumulator&&(pole==null||d.powerCoverRadius>pole.prefabDesc.powerCoverRadius))pole=it;if(d.isTurret&&d.turretType==ETurretType.Gauss)gauss=it;if(d.isTurret&&d.turretType==ETurretType.Laser)laser=it;}if(it.AmmoType==EAmmoType.Bullet&&(ammo==null||it.Ability>ammo.Ability))ammo=it;}Check(gen!=null&&pole!=null&&gauss!=null&&laser!=null&&ammo!=null,"Missing combat prototypes");int fuel=0;foreach(int id in ItemProto.fuelNeeds[gen.prefabDesc.fuelMask])if(fuel==0||LDB.items.Select(id).HeatValue>LDB.items.Select(fuel).HeatValue)fuel=id;
  var generator=Build(gen.ID,centre+forward*32);Build(pole.ID,centre+forward*24);turrets=new int[4];for(int i=0;i<4;i++)turrets[i]=Build(i%2==0?gauss.ID:laser.ID,centre+forward*20+right*(i*5-7.5f));yield return new WaitForSecondsRealtime(2);Check(F.InsertInto(generator,0,fuel,10,0,out var unused)==10,"Combat generator feed failed");for(int i=0;i<4;i+=2){int id=F.entityPool[turrets[i]].turretId;Check(F.defenseSystem.turrets.buffer[id].SetNewItem(ammo.ID,100,0),"Turret ammo rejected");r.initialAmmo+=100;}
  var player=GameMain.mainPlayer;player.position=(centre+forward*75).normalized*(F.planet.realRadius+1);Write("fighting");deadline=Time.realtimeSinceStartup+180;bool cap=false;while(Time.realtimeSinceStartup<deadline){yield return new WaitForSecondsRealtime(1);Write("fighting");if(r.damage>0&&!cap){cap=true;yield return Capture("firing");}if(r.damage>0&&r.kills>0&&r.remainingAmmo<r.initialAmmo)break;}
  Check(r.damage>0&&r.kills>0&&r.remainingAmmo<r.initialAmmo,"Original turret fire/damage/kill not all observed");long damage=r.damage;int kills=r.kills;r.saveName="PortCombat-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(GameSave.SaveCurrentGame(r.saveName),"Combat save failed");yield return null;DSPGame.StartGame(r.saveName);yield return null;deadline=Time.realtimeSinceStartup+180;while((!GameMain.isRunning||DSPGame.IsMenuDemo||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded)&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(1);Check(GameMain.isRunning&&!DSPGame.IsMenuDemo&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded,"Combat reload timeout");Write("reloaded");r.reloaded=r.damage>=damage&&r.kills>=kills;Check(r.reloaded,"Combat counters lost after reload");yield return Capture("reloaded");Passed=true;Write("passed");
 }
 public static IEnumerator SafeRun(){var run=Run();while(true){object next=null;bool more=false;Exception err=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){err=e;}if(err!=null){r.errors.Add(err.ToString());Write("failed");Debug.LogError("Combat audit: "+err);break;}if(!more)break;yield return next;}((IDisposable)run).Dispose();}
}
